import java.util.*;

class Solution {
  public int deleteTreeNodes(int nodes, int[] parent, int[] value) {
    List<List<Integer>> children = new ArrayList<>();
    for (int i = 0; i < nodes; i++) children.add(new ArrayList<>());
    for (int i = 1; i < nodes; i++) children.get(parent[i]).add(i);
    return walk(0, children, value)[1];
  }

  // {subtree sum, nodes kept}; a zero-sum subtree keeps nothing
  private int[] walk(int node, List<List<Integer>> children, int[] value) {
    int sum = value[node], kept = 1;
    for (int c : children.get(node)) {
      int[] r = walk(c, children, value);
      sum += r[0];
      kept += r[1];
    }
    return new int[] {sum, sum == 0 ? 0 : kept};
  }
}
